changeSet.sql:
CREATE TABLE penalty_waivers ( id uuid NOT NULL PRIMARY KEY, created_at timestamp(6) with time zone NOT NULL, created_by varchar(255),
transaction_id uuid NOT NULL REFERENCES transactions (id), seller_tenant_id uuid NOT NULL REFERENCES organizations (id), buyer_user_id uuid NOT NULL REFERENCES users (id), schedule_version integer NOT NULL, instalment_sequence integer NOT NULL, amount numeric(19, 2) NOT NULL, reason varchar(500) NOT NULL, waived_by uuid NOT NULL REFERENCES users (id),
CONSTRAINT chk_penalty_waivers_amount CHECK (amount > 0) ); CREATE INDEX idx_penalty_waivers_transaction ON penalty_waivers (transaction_id, schedule_version, instalment_sequence); REVOKE UPDATE, DELETE, TRUNCATE ON penalty_waivers FROM ${appDbUsername}; COMMENT ON TABLE penalty_waivers IS 'An amount of a late-payment penalty a developer forgave, on one instalment of one schedule version, with a reason. Subtracted from the penalty when it is worked out; a higher step reached later is still owed beyond it. Never changed.';
